    correctKey: 'B',
    explanation: `VC試験は、スランプ試験が適用できない超硬練りコンクリートの締固め性を評価する試験である。振動台に固定した容器に試料を詰め、上部に円板を載せて振動を与え、コンクリート表面にモルタルが浮き上がって円板の下面全体に達するまでの時間を測定する。この時間をVC値と呼び、値が大きいほど硬練りで締固めに時間を要する。RCD用コンクリートでは、練上がりから締固めまでの時間経過や気温の影響を受けてVC値が変化するため、現場での管理が重要となる。

【図解】VC試験の評価
　項目｜内容｜判断
　測定量｜モルタルが浮き上がるまでの時間｜VC値と呼ぶ
　VC値が大きい｜硬練りで締固めに時間を要する｜締固め不足に注意
　VC値が小さい｜軟らかく締固めやすい｜過転圧や不陸に注意
　⇒ 気温や時間経過でVC値が変わるため現場管理が必要
　⚠ スランプ試験の代替であり強度や空気量の試験ではない`,
