    correctKey: 'C',
    explanation: `ひび割れは発生原因により分類される。施工的要因には沈下ひび割れ、コールドジョイント、型枠の変形や早期脱型によるものがある。材料的要因には乾燥収縮、自己収縮、水和熱による温度ひび割れ、アルカリシリカ反応がある。構造的要因には設計荷重を超える荷重、不同沈下、断面や配筋の不足によるものがある。環境的要因には凍害、火害、化学的侵食がある。補修方針は原因の特定から始まり、進行性の有無、環境条件、要求性能を踏まえて工法と時期を決める。

【図解】ひび割れの要因別分類
　要因｜代表的なひび割れ｜発生時期
　施工的要因｜沈下ひび割れ、コールドジョイント｜打込みから若材齢
　材料的要因｜乾燥収縮、温度ひび割れ、アルカリシリカ反応｜若材齢から長期
　構造的要因および環境的要因｜過大荷重、不同沈下、凍害、火害｜供用中
　⇒ 原因の特定が補修工法選定の出発点となる
　⚠ ひび割れ幅だけで補修の要否は決まらない`,
