【図解】ひび割れ形態と疑うべき劣化機構
　形態｜付随する現象｜疑う劣化機構
　鉄筋に沿う直線状｜錆汁とはく離｜中性化または塩害による鉄筋腐食
　無筋部の亀甲状｜ゲルの析出と白色の滲出｜アルカリシリカ反応
　表面の微細ひび割れ｜薄片状のはく離｜凍害
