    correctKey: 'B',
    explanation: `反発度は打撃方向によって系統的に変化する。重錘に作用する重力の向きが異なるため、鉛直上向きに打撃する天井面では小さめの値が、鉛直下向きに打撃する床面では大きめの値が得られる。したがって水平打撃を基準として、上向きでは正の補正値を加算し、下向きでは負の補正値を加算する。この設問では30に2.5を加えて補正後の反発度32.5を得て、換算式に代入して約23.3 N/mm²となる。補正を怠ると天井面の強度を過小に、床面の強度を過大に評価する。

【図解】打撃方向による補正の考え方
　打撃方向｜得られる反発度の傾向｜補正
　鉛直上向き（天井面）｜小さめに出る｜正の値を加算
　水平（壁面）｜基準となる｜補正なし
　鉛直下向き（床面）｜大きめに出る｜負の値を加算
　代入：－18.0＋1.27×(30＋2.5)＝－18.0＋41.28＝23.3 N/mm²★
　⚠ 補正の符号を誤ると強度評価が系統的にずれる`,
