【図解】反発度測定の手順と注意点
　項目｜標準的な扱い｜理由
　測定点数｜1か所につき20点程度｜ばらつきを平均化する
　異常値｜平均から著しく外れた値を除外｜骨材直上や豆板の影響を排除
　測定面｜砥石で平滑にし仕上げ材を除去｜表面状態の影響を減らす
