    correctKey: 'A',
    explanation: `電磁誘導法は、探査コイルに交流電流を流して磁界を発生させ、鉄筋によって生じる磁界の変化を検出することで、鉄筋の位置、かぶり、径を推定する非破壊試験である。かぶりの測定にもっとも一般的に用いられ、含水状態の影響が小さい点が利点である。一方で対象は磁性体である鉄筋などの金属に限られ、非金属の埋設物は検出できない。また鉄筋が密に配置された部位や、かぶりが大きい場合には精度が低下する。正確なかぶりが必要な場合は、はつりによる直接確認と併用する。

【図解】電磁誘導法の適用と限界
　項目｜内容｜備考
　測定対象｜鉄筋の位置、かぶり、径｜磁性体である金属に限られる
　利点｜含水の影響が小さく簡便｜かぶり測定の標準的手法
　限界｜密な配筋や大きなかぶりで精度低下｜はつりによる確認と併用
　⇒ 電磁波レーダ法と併用すると信頼性が高まる
　⚠ 非金属の埋設物は検出できない`,
    difficulty: 'basic',
